from pathlib import Path
import json,hashlib,wntr,importlib.metadata as md
ROOT=Path(__file__).resolve().parents[1]
assert not (ROOT/'data/problem.json').exists(),'Frozen problem already exists; create a new version rather than overwriting'
w=wntr.network.WaterNetworkModel(str(ROOT/'data/hanoi-original.inp'));w.options.hydraulic.accuracy=1e-8;w.options.hydraulic.trials=200;w.options.hydraulic.unbalanced='STOP';w.options.hydraulic.unbalanced_value=0;w.options.hydraulic.demand_model='DDA';w.options.time.duration=0
for _,p in w.pipes():p.diameter=1.016
wntr.network.write_inpfile(w,str(ROOT/'data/hanoi-design.inp'),units='CMH',version=2.2)
ref=[40]*9+[30,24,24,20,16,12,12,16,24,20,40,20,12,40,30,30,20,12,12,16,12,12,16,16,24]
assert len(ref)==34
spec={'network':'data/hanoi-design.inp','network_sha256':hashlib.sha256((ROOT/'data/hanoi-design.inp').read_bytes()).hexdigest(),'diameters_in':[12,16,20,24,30,40],'unit_cost_formula':'1.1 * diameter_inches ** 1.5 per meter','minimum_pressure_m':30.,'junctions':w.junction_name_list,'pipes':w.pipe_name_list,'length_m':[w.get_link(p).length for p in w.pipe_name_list],'reference_diameters_in':ref,'reference_source':'https://doi.org/10.3390/w14060851 Table8 (2022); printed cost uses rounded unit costs; our exact formula differs slightly','reference_reported_cost_rounded_catalog':6081115.4,'scenarios':{'nominal':[1.]*31,'uniform_110':[1.1]*31,'zone_a':[1.2 if int(n)<=16 else 1. for n in w.junction_name_list],'zone_b':[1. if int(n)<=16 else 1.2 for n in w.junction_name_list]},'tasks':{'nominal':['nominal'],'stress':['nominal','uniform_110','zone_a','zone_b']},'scenario_provenance':'Synthetic qualification scenarios chosen before search; not empirically calibrated demand forecasts; no real-system design certification'}
(ROOT/'data/problem.json').write_text(json.dumps(spec,indent=2)+'\n')
(ROOT/'research/protocol.json').write_text(json.dumps({'scope':'historical Hanoi diameter sizing, two explicitly separate tasks','reference':'reproduce published Table8 vector and nominal pressures before optimization','runs':'seeds419,503,719; each algorithm gets4000hydraulicdesign evaluations per task; each design evaluation checks all task scenarios','baseline':'published nominal layout; stress baseline repaired by greedy pressure-violation reduction then coordinate downsize; full setup evaluations counted separately','arms':'multistart feasible coordinate descent vs iterated multi-pipe perturbation and greedy repair/descent; equal evaluation budgets','acceptance':'each scenario minimum pressure>=30m,EPANET convergence without warnings, valid discrete catalog, independent WNTRSimulator check and flow/head residual audit','post_freeze':'20fixed random nodal demand multipliers in[1,1.2]; evaluate all retained designs after freeze; descriptive exposure,not universal robustness','limits':'no claimed published record; nominal/stress incomparable objectives; no wet-lab or infrastructure operation; all local simulation','stop':'one fixed round plus verifier corrections, no outcome-driven budget extension'},indent=2)+'\n')
(ROOT/'research/sources.json').write_text(json.dumps({'network_url':'https://www.exeter.ac.uk/v8media/universityofexeter/emps/research/cws/downloads/hanoi.inp','definition_url':'https://www.exeter.ac.uk/research/centres/cws/resources/benchmarks/','objective_check':'source/problemdef.c HAN section from Exeter source.zip; observed1.1D^1.5L','reference':'https://doi.org/10.3390/w14060851 Table8','wntr':'https://usepa.github.io/WNTR/hydraulics.html','data_rights':'Exeter offers files for research; explicit redistribution license not established. Local use only pending rights review. MIT pilot license does not cover inputs or published artifacts.','sha256':{str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in [ROOT/'data/hanoi-original.inp',ROOT/'data/hanoi-design.inp',ROOT/'data/published-pareto.txt',ROOT/'vendor/exeter-source.zip',ROOT/'research/sop-wdn.pdf']}},indent=2)+'\n')
print('Prepared 31 junctions,34 pipes,6 diameters,2tasks; WNTR',md.version('wntr'))
